import type {
  McpSyncRow,
  RoleResolution,
  SyncRequest,
  SyncResponse,
  SyncWrite,
} from "@agnostic/core";
import { describe, expect, it } from "vitest";
import { createTestContext } from "../test-context.js";
import { syncCommand } from "./sync.js";

const REPO = { id: "r7k2m4pqrs", name: "app", path: "/work/app", kind: "git" as const };
const HEADER =
  "<!-- generated by agn sync from .ag/instructions.md; edit that file, not this one -->";
const CLAUDE_MD = `${HEADER}\n\n@AGENTS.md\n`;

function cli(
  answer: Omit<SyncResponse, "roles" | "mcp"> & { roles?: RoleResolution[]; mcp?: McpSyncRow[] },
  cwd = "/work/app",
) {
  const response: SyncResponse = { roles: [], mcp: [], ...answer };
  const asked: { repoId: string; body: SyncRequest }[] = [];
  const test = createTestContext({
    client: {
      listRepos: () =>
        Promise.resolve({
          repos: [
            {
              ...REPO,
              addedAt: "",
              status: "active" as const,
              testCommand: null,
              pathPresent: true,
            },
          ],
          cursor: 0,
        }),
      syncRepo: (repoId, body) => {
        asked.push({ repoId, body });
        return Promise.resolve(response);
      },
    },
    cwd,
  });
  return { ...test, asked };
}

function write(over: Partial<SyncWrite> = {}): SyncWrite {
  return { file: "CLAUDE.md", action: "create", content: CLAUDE_MD, reason: null, ...over };
}

function resolution(over: Partial<RoleResolution> = {}): RoleResolution {
  return {
    workflow: "tiered",
    role: "architect",
    class: "research",
    pinned: null,
    profile: "claude-code:fable:native",
    harness: "claude-code",
    model: "fable",
    via: "recommended",
    reason: null,
    ...over,
  };
}

function mcp(over: Partial<McpSyncRow> = {}): McpSyncRow {
  return { server: "db", target: "claude-code", action: "written", reason: null, ...over };
}

describe("agn sync", () => {
  it("reports what it wrote, updated and left alone", async () => {
    const test = cli({
      applied: true,
      writes: [
        write(),
        write({ file: "AGENTS.md", action: "update", reason: "no header, same content" }),
      ],
    });
    await syncCommand(test.ctx).parseAsync(["--repo", REPO.id], { from: "user" });
    expect(test.out).toEqual(["wrote CLAUDE.md", "updated AGENTS.md (no header, same content)"]);
    expect(test.asked).toEqual([{ repoId: REPO.id, body: {} }]);
  });

  it("says unchanged when there was nothing to do", async () => {
    const test = cli({
      applied: true,
      writes: [write({ action: "unchanged" }), write({ file: "AGENTS.md", action: "unchanged" })],
    });
    await syncCommand(test.ctx).parseAsync(["--repo", REPO.id], { from: "user" });
    expect(test.out).toEqual(["unchanged CLAUDE.md", "unchanged AGENTS.md"]);
  });

  it("prints the content of every planned write on a dry run", async () => {
    const test = cli({
      applied: false,
      writes: [write(), write({ file: "AGENTS.md", action: "unchanged" })],
    });
    await syncCommand(test.ctx).parseAsync(["--repo", REPO.id, "--dry-run"], { from: "user" });
    expect(test.out).toEqual([
      "would write CLAUDE.md",
      "",
      `  ${HEADER}`,
      "",
      "  @AGENTS.md",
      "unchanged AGENTS.md",
    ]);
    expect(test.asked[0]?.body).toEqual({ dryRun: true });
  });

  it("prints a conflict with its reason and no content", async () => {
    const test = cli({
      applied: false,
      writes: [write({ action: "conflict", reason: "no header, hand-edited" })],
    });
    await syncCommand(test.ctx).parseAsync(["--repo", REPO.id, "--dry-run"], { from: "user" });
    expect(test.out).toEqual(["conflict CLAUDE.md: no header, hand-edited"]);
  });

  it("passes --force through", async () => {
    const test = cli({ applied: true, writes: [] });
    await syncCommand(test.ctx).parseAsync(["--repo", REPO.id, "--force"], { from: "user" });
    expect(test.asked[0]?.body).toEqual({ force: true });
  });

  it("says where to register a repo when the current directory is not one", async () => {
    const test = cli({ applied: true, writes: [] }, "/elsewhere");
    await expect(syncCommand(test.ctx).parseAsync([], { from: "user" })).rejects.toMatchObject({
      code: "repo-not-resolved",
      hint: "Run `agn add .` here, or pass --repo <id or path>.",
    });
  });

  it("prints the daemon's answer verbatim with --json", async () => {
    const response = { applied: true, writes: [write()], roles: [resolution()], mcp: [mcp()] };
    const test = cli(response);
    test.ctx.json = true;
    await syncCommand(test.ctx).parseAsync(["--repo", REPO.id], { from: "user" });
    expect(JSON.parse(test.out.join("\n"))).toEqual(response);
  });

  it("says what every workflow role compiled to, after the files", async () => {
    const test = cli({
      applied: true,
      writes: [write({ file: ".claude/agents/architect.md" })],
      roles: [
        resolution(),
        resolution({
          role: "reviewer",
          class: "review",
          pinned: "codex:default:native",
          profile: "codex:default:native",
          harness: "codex",
          model: null,
          via: "pinned",
        }),
        resolution({
          role: "test-writer",
          class: "implement",
          pinned: "codex:gpt-5:native",
          profile: "claude-code:opus:native",
          model: "opus",
          via: "replaced",
          reason: "codex:gpt-5:native is not a profile on this machine",
        }),
      ],
    });
    await syncCommand(test.ctx).parseAsync(["--repo", REPO.id], { from: "user" });
    expect(test.out).toEqual([
      "wrote .claude/agents/architect.md",
      "tiered/architect: claude-code:fable:native (recommended for research)",
      "tiered/reviewer: codex:default:native (pinned)",
      "tiered/test-writer: claude-code:opus:native (pin codex:gpt-5:native replaced: codex:gpt-5:native is not a profile on this machine; recommended for implement)",
    ]);
  });

  it("prints the same role lines under a dry run's plan", async () => {
    const test = cli({
      applied: false,
      writes: [write({ action: "unchanged" })],
      roles: [resolution()],
    });
    await syncCommand(test.ctx).parseAsync(["--repo", REPO.id, "--dry-run"], { from: "user" });
    expect(test.out).toEqual([
      "unchanged CLAUDE.md",
      "tiered/architect: claude-code:fable:native (recommended for research)",
    ]);
  });

  it("names the three files each MCP server was written to", async () => {
    const test = cli({
      applied: true,
      writes: [write({ file: ".mcp.json" })],
      mcp: [mcp(), mcp({ target: "opencode" }), mcp({ target: "codex", action: "unchanged" })],
    });
    await syncCommand(test.ctx).parseAsync(["--repo", REPO.id], { from: "user" });
    expect(test.out).toEqual([
      "wrote .mcp.json",
      "mcp db: .mcp.json, opencode.json, ~/.codex/config.toml",
    ]);
  });

  it("says which target was skipped and why, in the server's own line", async () => {
    const test = cli({
      applied: false,
      writes: [],
      mcp: [
        mcp(),
        mcp({ target: "opencode" }),
        mcp({
          target: "codex",
          action: "skipped",
          reason: "Codex forwards a variable only under its own name",
        }),
      ],
    });
    await syncCommand(test.ctx).parseAsync(["--repo", REPO.id, "--dry-run"], { from: "user" });
    expect(test.out).toEqual([
      "mcp db: .mcp.json, opencode.json, codex skipped (Codex forwards a variable only under its own name)",
    ]);
  });

  it("says a server skipped everywhere once", async () => {
    const reason = "GITHUB_TOKEN looks like a secret; write $NAME and set NAME in your shell";
    const test = cli({
      applied: true,
      writes: [],
      mcp: [
        mcp({ server: "issues", action: "skipped", reason }),
        mcp({ server: "issues", target: "opencode", action: "skipped", reason }),
        mcp({ server: "issues", target: "codex", action: "skipped", reason }),
      ],
    });
    await syncCommand(test.ctx).parseAsync(["--repo", REPO.id], { from: "user" });
    expect(test.out).toEqual([`mcp issues: skipped (${reason})`]);
  });
});
